// Assembles the live demo on the landing page.
//
// The demo is a real published tour: the same player files the editor writes
// into an export, plus the manifest and media in /demo. Building it from the
// export modules, instead of committing a copy, means the demo can never drift
// from what the editor produces. Output goes to public/demo, which is
// gitignored and regenerated by `npm run dev` and `npm run build`.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { embedHtml, playerHtml, playerScript, playerStyles } from '../src/export-player.js'
import { pinIcons } from '../src/pin-icons.js'

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)))
const source = path.join(root, 'demo')
const out = path.join(root, 'public', 'demo')
const three = path.join(root, 'node_modules', 'three', 'build')

fs.rmSync(out, { recursive: true, force: true })
fs.mkdirSync(out, { recursive: true })
fs.cpSync(path.join(source, 'media'), path.join(out, 'media'), { recursive: true })
fs.copyFileSync(path.join(source, 'tour.json'), path.join(out, 'tour.json'))
fs.copyFileSync(path.join(three, 'three.module.min.js'), path.join(out, 'three.module.js'))
fs.copyFileSync(path.join(three, 'three.core.min.js'), path.join(out, 'three.core.min.js'))

const iconPaths = Object.fromEntries(Object.entries(pinIcons).map(([name, icon]) => [name, icon.path]))
fs.writeFileSync(path.join(out, 'index.html'), playerHtml)
fs.writeFileSync(path.join(out, 'embed.html'), embedHtml)
fs.writeFileSync(path.join(out, 'styles.css'), playerStyles)
fs.writeFileSync(path.join(out, 'player.js'), playerScript.replace('__PIN_ICONS__', JSON.stringify(iconPaths)))

console.log(`demo tour written to ${path.relative(root, out)}`)
